# -*- coding: utf-8 -*-
SVGS = ['<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="26" text-anchor="middle" font-size="14.5" font-weight="bold" fill="#0f172a">NAMAZIN FARZLARI: ŞARTLARI (DIŞINDA) VE RÜKÜNLERİ (İÇİNDE)</text>\n  <rect x="22" y="42" width="320" height="175" rx="10" fill="#eff6ff" stroke="#2563eb" stroke-width="2"/>\n  <text x="182" y="64" text-anchor="middle" font-size="12.5" font-weight="bold" fill="#1e40af">NAMAZIN ŞARTLARI (DIŞINDAKİ 6 FARZ)</text>\n  <text x="35" y="88" font-size="11.2" fill="#1e3a8a">1. Hadesten Taharet: Abdest / gusül / teyemmüm</text>\n  <text x="35" y="108" font-size="11.2" fill="#1e3a8a">2. Necâsetten Taharet: Beden, elbise ve yer temizliği</text>\n  <text x="35" y="128" font-size="11.2" fill="#1e3a8a">3. Setr-i Avret: Örtünmesi gereken yerleri örtmek</text>\n  <text x="35" y="148" font-size="11.2" fill="#1e3a8a">4. İstikbâl-i Kıble: Kâbe (Mescid-i Harâm) yönüne dönmek</text>\n  <text x="35" y="168" font-size="11.2" fill="#1e3a8a">5. Vakit: Namazın kendi vaktinin girmiş olması</text>\n  <text x="35" y="188" font-size="11.2" fill="#1e3a8a">6. Niyet: Kılınacak namazı kalben belirlemek</text>\n  <rect x="358" y="42" width="320" height="175" rx="10" fill="#f0fdf4" stroke="#16a34a" stroke-width="2"/>\n  <text x="518" y="64" text-anchor="middle" font-size="12.5" font-weight="bold" fill="#166534">NAMAZIN RÜKÜNLERİ (İÇİNDEKİ 6 FARZ)</text>\n  <text x="370" y="88" font-size="11.2" fill="#14532d">1. İftitah Tekbiri: «Allâhü Ekber» diyerek başlamak</text>\n  <text x="370" y="108" font-size="11.2" fill="#14532d">2. Kıyam: Namazda ayakta durmak</text>\n  <text x="370" y="128" font-size="11.2" fill="#14532d">3. Kıraat: Kıyamda Kur\'an\'dan ayet/sure okumak</text>\n  <text x="370" y="148" font-size="11.2" fill="#14532d">4. Rükû: Elleri dizlere koyarak eğilmek</text>\n  <text x="370" y="168" font-size="11.2" fill="#14532d">5. Sücûd (Secde): Her rekâtta iki kez secdeye varmak</text>\n  <text x="370" y="188" font-size="11.2" fill="#14532d">6. Ka\'de-i Ahîre: Son oturuşta teşehhüd miktarı oturmak</text>\n  <rect x="22" y="224" width="656" height="26" rx="6" fill="#e2e8f0"/>\n  <text x="350" y="241" text-anchor="middle" font-size="11.5" font-weight="bold" fill="#1e293b">On iki farzdan herhangi biri eksik olursa namaz sahih (geçerli) olmaz; sehiv secdesiyle de telafi edilemez.</text>\n</svg>', '<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="26" text-anchor="middle" font-size="14.5" font-weight="bold" fill="#0f172a">NAMAZIN VACİPLERİ, SÜNNETLERİ VE TA\'DÎL-İ ERKÂN</text>\n  <rect x="22" y="42" width="320" height="175" rx="10" fill="#faf5ff" stroke="#9333ea" stroke-width="2"/>\n  <text x="182" y="64" text-anchor="middle" font-size="12.5" font-weight="bold" fill="#6b21a8">NAMAZIN BAŞLICA VACİPLERİ</text>\n  <text x="35" y="88" font-size="11.2" fill="#581c87">• Kıraatte Fâtiha-i Şerîfe okumak ve zamm-ı sure eklemek</text>\n  <text x="35" y="112" font-size="11.2" fill="#581c87">• Üç ve dört rekâtlı namazlarda ilk oturuş (Ka\'de-i Ûlâ)</text>\n  <text x="35" y="136" font-size="11.2" fill="#581c87">• İlk ve son oturuşlarda «Ettehiyyâtü» duasını okumak</text>\n  <text x="35" y="160" font-size="11.2" fill="#581c87">• Vitir namazında Kunut tekbiri almak ve Kunut okumak</text>\n  <text x="35" y="184" font-size="11.2" fill="#581c87">• Ta\'dîl-i erkâna riayet etmek ve sonunda selam vermek</text>\n  <rect x="358" y="42" width="320" height="175" rx="10" fill="#fff7ed" stroke="#ea580c" stroke-width="2"/>\n  <text x="518" y="64" text-anchor="middle" font-size="12.5" font-weight="bold" fill="#9a3412">NAMAZIN SÜNNETLERİ VE ÂDÂBI</text>\n  <text x="370" y="88" font-size="11.2" fill="#7c2d12">• Farz namazlardan önce ezan ve kamet okumak</text>\n  <text x="370" y="112" font-size="11.2" fill="#7c2d12">• İlk rekâtta Sübhâneke, Eûzü-Besmele okumak</text>\n  <text x="370" y="136" font-size="11.2" fill="#7c2d12">• Rükû ve secdelerde üçer defa tesbih okumak</text>\n  <text x="370" y="160" font-size="11.2" fill="#7c2d12">• Son oturuşta Salli-Bârik ve Rabbenâ dualarını okumak</text>\n  <text x="370" y="184" font-size="11.2" fill="#7c2d12">• Huşû, ihlas ve sükûnet içinde kıyama durmak</text>\n  <rect x="22" y="224" width="656" height="26" rx="6" fill="#e2e8f0"/>\n  <text x="350" y="241" text-anchor="middle" font-size="11.5" font-weight="bold" fill="#1e293b">Ta\'dîl-i erkân; rükû, kavme, secde ve celsede organların en az bir sübhânallah diyecek kadar sakinleşmesidir.</text>\n</svg>', '<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="26" text-anchor="middle" font-size="14.5" font-weight="bold" fill="#0f172a">NAMAZI BOZAN DURUMLAR (MÜFSİDLER) VE SEHİV SECDESİ</text>\n  <rect x="22" y="42" width="320" height="175" rx="10" fill="#fef2f2" stroke="#dc2626" stroke-width="2"/>\n  <text x="182" y="64" text-anchor="middle" font-size="12.5" font-weight="bold" fill="#991b1b">NAMAZI BOZAN BAŞLICA DURUMLAR</text>\n  <text x="35" y="88" font-size="11.2" fill="#7f1d1d">• Namaz içinde dünya kelamı konuşmak veya selam almak</text>\n  <text x="35" y="112" font-size="11.2" fill="#7f1d1d">• Bir şey yemek veya içmek</text>\n  <text x="35" y="136" font-size="11.2" fill="#7f1d1d">• Amel-i kesîr (Dışarıdan bakanın namazda değil sanacağı hareket)</text>\n  <text x="35" y="160" font-size="11.2" fill="#7f1d1d">• Göğsü kıbleden çevirmek veya abdestin bozulması</text>\n  <text x="35" y="184" font-size="11.2" fill="#7f1d1d">• Yanındakinin duyacağı şekilde gülmek (kahkaha abdesti de bozar)</text>\n  <rect x="358" y="42" width="320" height="175" rx="10" fill="#ecfdf5" stroke="#059669" stroke-width="2"/>\n  <text x="518" y="64" text-anchor="middle" font-size="12.5" font-weight="bold" fill="#065f46">SEHİV (YANILMA) SECDESİ VE UYGULANIŞI</text>\n  <text x="370" y="88" font-size="11.2" fill="#064e3b">• Gerektiren Durumlar: Bir farzın geciktirilmesi (tehir) veya</text>\n  <text x="370" y="108" font-size="11.2" fill="#064e3b">  bir vacibin unutularak terk edilmesi / geciktirilmesi</text>\n  <text x="370" y="132" font-size="11.2" fill="#064e3b">• Yapılışı: Son oturuşta Ettehiyyâtü okunduktan sonra</text>\n  <text x="370" y="152" font-size="11.2" fill="#064e3b">  sağa selam verilir → peş peşe 2 secde yapılır →</text>\n  <text x="370" y="172" font-size="11.2" fill="#064e3b">  oturulup Ettehiyyâtü, Salli-Bârik, Rabbenâ okunur ve</text>\n  <text x="370" y="190" font-size="11.2" fill="#064e3b">  iki tarafa selam verilerek namaz tamamlanır.</text>\n  <rect x="22" y="224" width="656" height="26" rx="6" fill="#e2e8f0"/>\n  <text x="350" y="241" text-anchor="middle" font-size="11.5" font-weight="bold" fill="#1e293b">Bir vacip kasten terk edilirse sehiv secdesi yeterli olmaz; namazın yeniden kılınması (iâde) vacip olur.</text>\n</svg>']

def uygula(v):
    for i, b in enumerate(v.get("bolumler", [])):
        if i < len(SVGS):
            b["gorsel"] = SVGS[i]
